lv_obj_t *img3;
static int16_t fast_angle = 0;
static int16_t slow_angle = 0;
static void timer_fast_cb(lv_timer_t *timer)
{
    fast_angle += 30; // 每次旋转30度，你可以调整
    lv_img_set_angle(img3, fast_angle);
}

static void timer_slow_cb(lv_timer_t *timer)
{
    slow_angle += 6; // 每分钟旋转6度（即秒针走一圈，分针走6度）
    lv_img_set_angle(img2, slow_angle);
}
