void lv_example_zoom(void)
{
    lv_obj_t *img = lv_image_create(lv_screen_active());
    lv_image_set_src(img, PIC_ADDR(HRS));
    // lv_obj_add_event_cb(img, get_img_layer_event_cb, LV_EVENT_DRAW_MAIN_BEGIN, NULL);
    lv_obj_align(img, LV_ALIGN_CENTER, -60, 0); // 居中显示
    lv_img_set_angle(img, 900);
    lv_img_set_pivot(img, 77 / 2, 67 / 2);
    lv_obj_t *img2 = lv_image_create(lv_screen_active());
    lv_image_set_src(img2, PIC_ADDR(HRS));
    lv_obj_align(img2, LV_ALIGN_CENTER, 60, 0); // 居中显示
    lv_img_set_angle(img2, 263);
    lv_img_set_pivot(img2, 77 / 2, 67 / 2);

    lv_obj_t *img3 = lv_image_create(lv_screen_active());
    lv_image_set_src(img3, PIC_ADDR(HRS));
    lv_obj_align(img3, LV_ALIGN_CENTER, 0, 75); // 居中显示
    lv_img_set_angle(img3, 1800);
    lv_img_set_pivot(img3, 77 / 2, 67 / 2);

    lv_obj_t *img4 = lv_image_create(lv_screen_active());
    lv_image_set_src(img4, PIC_ADDR(HRS));
    lv_obj_align(img4, LV_ALIGN_CENTER, 0, -75); // 下
    lv_img_set_angle(img4, 36);
    lv_img_set_pivot(img4, 77 / 2, 67 / 2);

    lv_anim_t a;
    lv_anim_init(&a);
    lv_anim_set_var(&a, img4);
    lv_anim_set_exec_cb(&a, (lv_anim_exec_xcb_t)lv_img_set_zoom);
    lv_anim_set_values(&a, 256, 512); // 从100%到200%
    lv_anim_set_time(&a, 500);
    lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
    lv_anim_start(&a);
}

